using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

namespace AkilliKisayol {
 public static class ModelWire {
  static string Text(object value){if(value is string)return (string)value;var blocks=value as object[];if(blocks==null)return null;var result=new StringBuilder();foreach(var block in blocks){var part=block as Dictionary<string,object>;if(part==null)continue;object kind,content;if(part.TryGetValue("type",out kind)&&(Convert.ToString(kind)=="text"||Convert.ToString(kind)=="output_text")&&part.TryGetValue("text",out content)){if(content is string)result.Append((string)content);else{var nested=content as Dictionary<string,object>;if(nested!=null&&nested.ContainsKey("value")&&nested["value"] is string)result.Append((string)nested["value"]);}}}return result.ToString();}
  public static string Completion(string body){
   var root=LocalLlm.Json().DeserializeObject(body) as Dictionary<string,object>;object value;var choices=root!=null&&root.TryGetValue("choices",out value)?value as object[]:null;
   if(choices==null||choices.Length==0)throw new InvalidDataException("The server did not return a chat completion.");var choice=choices[0] as Dictionary<string,object>;if(choice==null)throw new InvalidDataException("Invalid chat completion choice.");string finish=choice.TryGetValue("finish_reason",out value)?value as string:null;if(finish=="length"||finish=="max_tokens")throw new InvalidDataException("The model reached its output token limit before completing the plan. Increase the output token budget in AI model settings.");if(finish=="content_filter")throw new InvalidDataException("The model server did not provide a completed response.");
   var message=choice.TryGetValue("message",out value)?value as Dictionary<string,object>:null;if(message==null)throw new InvalidDataException("The server response has no assistant message.");string content=message.TryGetValue("content",out value)?Text(value):null;if(!string.IsNullOrWhiteSpace(content)){if(finish!=null&&finish!="stop")throw new InvalidDataException("The server did not finish its response ("+finish+").");return content;}
   var calls=message.TryGetValue("tool_calls",out value)?value as object[]:null;Dictionary<string,object> function=null;if(calls!=null){if(calls.Length!=1)throw new InvalidDataException("The server returned multiple plan calls; a single complete plan is required.");var call=calls[0] as Dictionary<string,object>;if(call!=null&&call.TryGetValue("function",out value))function=value as Dictionary<string,object>;}else if(message.TryGetValue("function_call",out value))function=value as Dictionary<string,object>;
   if(function!=null&&function.TryGetValue("arguments",out value)){if(finish!=null&&finish!="stop"&&finish!="tool_calls"&&finish!="function_call")throw new InvalidDataException("The server did not finish its plan call.");if(value is string)return (string)value;if(value is Dictionary<string,object>)return LocalLlm.Json().Serialize(value);}
   throw new InvalidDataException("The model returned no final plan text. Choose a chat/instruction model or increase its output budget.");
  }
  static Dictionary<string,object> Parse(string text){return LocalLlm.Json().DeserializeObject(text) as Dictionary<string,object>;}
  public static Dictionary<string,object> Plan(string content,LlmRequest request){
   if(string.IsNullOrWhiteSpace(content))throw new InvalidDataException("The model returned an empty plan.");content=content.Trim().TrimStart('\uFEFF');if(content.StartsWith("<think>",StringComparison.Ordinal)&&!content.Contains("</think>"))throw new InvalidDataException("The model returned unfinished reasoning instead of a final plan.");content=Regex.Replace(content,@"^<think>[\s\S]*?</think>\s*|^</think>\s*","").Trim();if(content.StartsWith("```",StringComparison.Ordinal))content=Regex.Replace(content,@"^```(?:json)?\s*|\s*```$","",RegexOptions.IgnoreCase).Trim();Dictionary<string,object> root=null;
   try{root=Parse(content);}catch(ArgumentException){}
   if(root==null){var candidates=new List<Dictionary<string,object>>();int depth=0,start=-1;bool quoted=false,escape=false;for(int i=0;i<content.Length;i++){char c=content[i];if(depth==0){if(c=='{'){start=i;depth=1;quoted=escape=false;}continue;}if(quoted){if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='"')quoted=false;continue;}if(c=='"')quoted=true;else if(c=='{')depth++;else if(c=='}'&&--depth==0){try{var candidate=Parse(content.Substring(start,i-start+1));if(candidate!=null)candidates.Add(candidate);}catch(ArgumentException){}}}if(candidates.Count!=1)throw new InvalidDataException("Return one complete JSON plan without multiple alternatives.");root=candidates[0];}
   Default(root,"message","");Default(root,"notes",new object[0]);Default(root,"name","Shortcut");Default(root,"trigger","");
   object stepsValue;var steps=root.TryGetValue("steps",out stepsValue)?stepsValue as object[]:null;if(!root.ContainsKey("status"))root["status"]=steps!=null&&steps.Length>0?"ready":"clarify";
   if(!root.ContainsKey("app_id")||root["app_id"]==null){var apps=LlmProtocol.AppMap(request);string destination=AppIntegration.Target(request);bool opening=steps!=null&&steps.Any(s=>{var step=s as Dictionary<string,object>;return step!=null&&step.ContainsKey("kind")&&new[]{"open_app","open_resource","open_website","focus_app"}.Contains(Convert.ToString(step["kind"]));});string selected=destination.Length>0?destination:!opening?request.SelectedApp??"":"";root["app_id"]=apps.Where(p=>Rules.SameApp(p.Value,selected)).Select(p=>p.Key).FirstOrDefault()??"global";}
   if(steps!=null)foreach(var item in steps){var step=item as Dictionary<string,object>;if(step==null)continue;Default(step,"combo","");Default(step,"text","");if(!step.ContainsKey("kind")||Convert.ToString(step["kind"])!="wait")Default(step,"ms",0);object milliseconds;if(step.TryGetValue("ms",out milliseconds)){int number;if(milliseconds is string&&int.TryParse((string)milliseconds,System.Globalization.NumberStyles.None,System.Globalization.CultureInfo.InvariantCulture,out number))step["ms"]=number;else if(milliseconds is double&&(double)milliseconds>=0&&(double)milliseconds<=10000&&Math.Abs((double)milliseconds-Math.Round((double)milliseconds))<0.0000001)step["ms"]=(int)(double)milliseconds;else if(milliseconds is decimal&&(decimal)milliseconds>=0&&(decimal)milliseconds<=10000&&decimal.Truncate((decimal)milliseconds)==(decimal)milliseconds)step["ms"]=(int)(decimal)milliseconds;}}
   object status;if(root.TryGetValue("status",out status)&&(Convert.ToString(status)=="clarify"||Convert.ToString(status)=="unsupported"))root["steps"]=new object[0];
   return root;
  }
  static void Default(Dictionary<string,object> map,string key,object value){if(!map.ContainsKey(key)||map[key]==null)map[key]=value;}
 }
}
